"use client";

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { UserPlus, Mail, Shield, AlertCircle } from "lucide-react";
import { toast } from "sonner";
import { authenticatedFetch } from "@/lib/auth/api-client";

export default function SettingsPage() {
  const { user, shopId } = useAuth();
  const [memberEmail, setMemberEmail] = useState("");
  const [isInviting, setIsInviting] = useState(false);

  const handleInviteMember = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!memberEmail || !memberEmail.includes("@")) {
      toast.error("有効なメールアドレスを入力してください");
      return;
    }

    setIsInviting(true);
    
    try {
      const response = await authenticatedFetch("/api/admin/invite-member", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ memberEmail }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || "招待に失敗しました");
      }

      toast.success(`${memberEmail} に招待メールを送信しました`);
      setMemberEmail("");
    } catch (error) {
      console.error("Invite error:", error);
      const errorMessage = error instanceof Error ? error.message : "招待に失敗しました";
      
      if (errorMessage.includes("Only owners")) {
        toast.error("メンバーの招待はオーナーのみ実行できます");
      } else {
        toast.error(errorMessage);
      }
    } finally {
      setIsInviting(false);
    }
  };

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl font-semibold">設定</h1>
        <p className="text-sm text-gray-600 mt-1">
          アカウントとショップの設定を管理します
        </p>
      </div>

      {/* アカウント情報 */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Shield className="h-5 w-5" />
            アカウント情報
          </CardTitle>
          <CardDescription>
            現在ログイン中のアカウント情報
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label className="text-sm text-gray-600">メールアドレス</Label>
              <p className="text-sm font-medium mt-1">{user?.email || "-"}</p>
            </div>
            <div>
              <Label className="text-sm text-gray-600">ショップID</Label>
              <p className="text-sm font-mono mt-1">{shopId || "-"}</p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* メンバー招待（Owner のみ） */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <UserPlus className="h-5 w-5" />
            メンバー招待
          </CardTitle>
          <CardDescription>
            新しいメンバーをこのショップに招待します（オーナーのみ）
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleInviteMember} className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="memberEmail">招待するメールアドレス</Label>
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <Mail className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
                  <Input
                    id="memberEmail"
                    type="email"
                    placeholder="member@example.com"
                    value={memberEmail}
                    onChange={(e) => setMemberEmail(e.target.value)}
                    className="pl-9"
                    disabled={isInviting}
                    required
                  />
                </div>
                <Button type="submit" disabled={isInviting || !memberEmail}>
                  {isInviting ? "送信中..." : "招待を送信"}
                </Button>
              </div>
            </div>

            <div className="p-3 bg-blue-50 border border-blue-200 rounded-md">
              <div className="flex items-start gap-2">
                <AlertCircle className="h-4 w-4 text-blue-600 mt-0.5 flex-shrink-0" />
                <div className="text-sm text-blue-800">
                  <p className="font-medium mb-1">招待の流れ:</p>
                  <ol className="space-y-1 list-decimal list-inside">
                    <li>招待メールが送信されます</li>
                    <li>メンバーがメールのリンクからパスワードを設定</li>
                    <li>ログイン後、このショップにアクセス可能になります</li>
                  </ol>
                </div>
              </div>
            </div>
          </form>
        </CardContent>
      </Card>

      {/* Widget 設定 */}
      <WidgetSettings shopId={shopId} />
    </div>
  );
}
